import { GOOGLE_SHEETS_API_BASE } from "../const";
import type { GoogleServiceAccountAuth } from "../google-auth/GoogleServiceAccountAuth";
import type { GoogleSheetRangeUpdate, GoogleSheetRow } from "../types";

type GoogleSheetsValuesResponse = {
  values?: GoogleSheetRow[];
};

type GoogleSpreadsheetResponse = {
  sheets?: Array<{ properties?: { sheetId?: number; title?: string } }>;
};

export class GoogleSheetsClient {
  constructor(
    private readonly auth: GoogleServiceAccountAuth,
    private readonly spreadsheetId: string,
  ) {}

  async getValues(
    worksheetName: string,
    range: string,
  ): Promise<GoogleSheetRow[]> {
    const response = await this.request<GoogleSheetsValuesResponse>(
      `/values/${this.encodeRange(worksheetName, range)}`,
      { method: "GET" },
    );

    return response.values || [];
  }

  // One quota-counted read for related ranges; results preserve requested order.
  async getValuesBatch(
    ranges: Array<{ worksheetName: string; range: string }>,
  ): Promise<GoogleSheetRow[][]> {
    if (!ranges.length) return [];
    const query = new URLSearchParams();
    for (const { worksheetName, range } of ranges) {
      query.append("ranges", `${quoteWorksheetName(worksheetName)}!${range}`);
    }
    const response = await this.request<{ valueRanges?: GoogleSheetsValuesResponse[] }>(
      `/values:batchGet?${query.toString()}`, { method: "GET" },
    );
    if (response.valueRanges?.length !== ranges.length) {
      throw new Error("Google Sheets batch read returned an incomplete set of ranges.");
    }
    return response.valueRanges.map((range) => range.values || []);
  }

  async appendValues(
    worksheetName: string,
    range: string,
    values: GoogleSheetRow[],
    inputOption: "USER_ENTERED" | "RAW" = "USER_ENTERED",
  ): Promise<void> {
    await this.request(
      `/values/${this.encodeRange(
        worksheetName,
        range,
      )}:append?valueInputOption=${inputOption}&insertDataOption=INSERT_ROWS`,
      {
        method: "POST",
        body: JSON.stringify({ values }),
      },
    );
  }

  async updateValues(
    worksheetName: string,
    range: string,
    values: GoogleSheetRow[],
    inputOption: "USER_ENTERED" | "RAW" = "USER_ENTERED",
  ): Promise<void> {
    await this.request(
      `/values/${this.encodeRange(
        worksheetName,
        range,
      )}?valueInputOption=${inputOption}`,
      {
        method: "PUT",
        body: JSON.stringify({ values }),
      },
    );
  }

  async batchUpdateValues(
    worksheetName: string,
    updates: GoogleSheetRangeUpdate[],
  ): Promise<void> {
    if (updates.length === 0) return;
    await this.request("/values:batchUpdate", {
      method: "POST",
      body: JSON.stringify({
        valueInputOption: "USER_ENTERED",
        data: updates.map(({ range, values }) => ({
          range: `${quoteWorksheetName(worksheetName)}!${range}`,
          majorDimension: "ROWS",
          values,
        })),
      }),
    });
  }

  async clearValues(worksheetName: string, range: string): Promise<void> {
    await this.request(
      `/values/${this.encodeRange(worksheetName, range)}:clear`,
      {
        method: "POST",
        body: JSON.stringify({}),
      },
    );
  }

  async deleteRow(worksheetName: string, rowNumber: number): Promise<void> {
    if (!Number.isInteger(rowNumber) || rowNumber < 2) {
      throw new Error("Only data rows can be deleted from Google Sheets.");
    }

    const spreadsheet = await this.request<GoogleSpreadsheetResponse>(
      "?fields=sheets.properties(sheetId,title)",
      { method: "GET" },
    );
    const worksheet = spreadsheet.sheets?.find(
      (sheet) => sheet.properties?.title === worksheetName,
    );
    const sheetId = worksheet?.properties?.sheetId;
    if (sheetId === undefined) {
      throw new Error(`Google Sheets worksheet not found: ${worksheetName}`);
    }

    await this.request(":batchUpdate", {
      method: "POST",
      body: JSON.stringify({
        requests: [{
          deleteDimension: {
            range: {
              sheetId,
              dimension: "ROWS",
              startIndex: rowNumber - 1,
              endIndex: rowNumber,
            },
          },
        }],
      }),
    });
  }

  async ensureWorksheet(worksheetName: string): Promise<void> {
    const spreadsheet = await this.request<GoogleSpreadsheetResponse>(
      "?fields=sheets.properties.title",
      { method: "GET" },
    );
    const exists = spreadsheet.sheets?.some(
      (sheet) => sheet.properties?.title === worksheetName,
    );
    if (exists) return;

    await this.request(":batchUpdate", {
      method: "POST",
      body: JSON.stringify({
        requests: [{ addSheet: { properties: { title: worksheetName } } }],
      }),
    });
  }

  private async request<T = unknown>(
    path: string,
    init: RequestInit,
  ): Promise<T> {
    const accessToken = await this.auth.getAccessToken();
    const response = await fetch(
      `${GOOGLE_SHEETS_API_BASE}/${encodeURIComponent(
        this.spreadsheetId,
      )}${path}`,
      {
        ...init,
        headers: {
          Authorization: `Bearer ${accessToken}`,
          Accept: "application/json",
          "Content-Type": "application/json",
          ...init.headers,
        },
      },
    );

    if (!response.ok) {
      const errorBody = await response.text();
      throw new Error(
        `Google Sheets API request failed: ${response.status} ${errorBody}`,
      );
    }

    if (response.status === 204) {
      return undefined as T;
    }

    return (await response.json()) as T;
  }

  private encodeRange(worksheetName: string, range: string): string {
    return encodeURIComponent(`${quoteWorksheetName(worksheetName)}!${range}`);
  }
}

function quoteWorksheetName(worksheetName: string): string {
  return `'${worksheetName.replace(/'/g, "''")}'`;
}

import { GOOGLE_TOKEN_URL } from "./const";
import type {
  GoogleAccessToken,
  IGoogleAccessTokenProvider,
} from "./types";

export abstract class GoogleAccessTokenProvider
  implements IGoogleAccessTokenProvider
{
  protected accessToken: GoogleAccessToken | null = null;

  abstract getAccessToken(): Promise<string>;

  protected getCachedAccessToken(): string | null {
    if (this.accessToken && this.accessToken.expiresAt > Date.now() + 60_000) {
      return this.accessToken.accessToken;
    }

    return null;
  }

  protected setAccessToken(
    accessToken: string,
    expiresInSeconds: number,
  ): string {
    this.accessToken = {
      accessToken,
      expiresAt: Date.now() + expiresInSeconds * 1000,
    };

    return this.accessToken.accessToken;
  }

  protected async exchangeAccessToken(body: URLSearchParams): Promise<Response> {
    return fetch(GOOGLE_TOKEN_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body,
    });
  }
}

import { GoogleAccessTokenProvider } from "./GoogleAccessTokenProvider";
import type { IGoogleAccessTokenProvider } from "./types";

export type GoogleOAuthRefreshTokenAuthConfig = {
  clientId: string;
  clientSecret: string;
  refreshToken: string;
};

export class GoogleOAuthRefreshTokenAuth
  extends GoogleAccessTokenProvider
  implements IGoogleAccessTokenProvider
{
  constructor(private readonly config: GoogleOAuthRefreshTokenAuthConfig) {
    super();
  }

  async getAccessToken(): Promise<string> {
    const cachedAccessToken = this.getCachedAccessToken();
    if (cachedAccessToken) return cachedAccessToken;

    const response = await this.exchangeAccessToken(
      new URLSearchParams({
        client_id: this.config.clientId,
        client_secret: this.config.clientSecret,
        refresh_token: this.config.refreshToken,
        grant_type: "refresh_token",
      }),
    );

    if (!response.ok) {
      const errorBody = await response.text();
      const googleError = parseGoogleOAuthError(errorBody);
      throw new Error(
        [
          `Google OAuth refresh failed: ${response.status}`,
          googleError
            ? `${googleError.error}: ${googleError.errorDescription}`
            : errorBody,
        ].join(" "),
      );
    }

    const payload = (await response.json()) as {
      access_token: string;
      expires_in: number;
    };
    return this.setAccessToken(payload.access_token, payload.expires_in);
  }
}

function parseGoogleOAuthError(
  value: string,
): { error: string; errorDescription: string } | null {
  try {
    const payload = JSON.parse(value) as {
      error?: string;
      error_description?: string;
    };

    if (!payload.error) return null;

    return {
      error: payload.error,
      errorDescription: payload.error_description || "No description",
    };
  } catch {
    return null;
  }
}

import { GOOGLE_TOKEN_URL } from "./const";
import type { IGoogleAccessTokenProvider } from "./types";
import { GoogleAccessTokenProvider } from "./GoogleAccessTokenProvider";
import { signJwt } from "./utils/jwt";

export type GoogleServiceAccountAuthConfig = {
  serviceAccountEmail: string;
  serviceAccountPrivateKey: string;
  scopes: string[];
};

export class GoogleServiceAccountAuth
  extends GoogleAccessTokenProvider
  implements IGoogleAccessTokenProvider
{
  constructor(private readonly config: GoogleServiceAccountAuthConfig) {
    super();

    if (!config.serviceAccountEmail.trim()) {
      throw new Error("Google service account email is required.");
    }

    if (!config.serviceAccountPrivateKey.trim()) {
      throw new Error("Google service account private key is required.");
    }

    if (config.scopes.length === 0) {
      throw new Error("At least one Google OAuth scope is required.");
    }
  }

  async getAccessToken(): Promise<string> {
    const cachedAccessToken = this.getCachedAccessToken();
    if (cachedAccessToken) return cachedAccessToken;

    const nowSeconds = Math.floor(Date.now() / 1000);
    const assertion = signJwt(
      {
        alg: "RS256",
        typ: "JWT",
      },
      {
        iss: this.config.serviceAccountEmail,
        scope: this.config.scopes.join(" "),
        aud: GOOGLE_TOKEN_URL,
        exp: nowSeconds + 3600,
        iat: nowSeconds,
      },
      this.config.serviceAccountPrivateKey,
    );

    const response = await this.exchangeAccessToken(
      new URLSearchParams({
        grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer",
        assertion,
      }),
    );

    if (!response.ok) {
      const errorBody = await response.text();
      throw new Error(
        `Google OAuth token request failed: ${response.status} ${errorBody}`,
      );
    }

    const payload = await readAccessTokenPayload(response);
    return this.setAccessToken(payload.accessToken, payload.expiresIn);
  }
}

async function readAccessTokenPayload(
  response: Response,
): Promise<{ accessToken: string; expiresIn: number }> {
  const payload = (await response.json()) as unknown;

  if (!isRecord(payload)) {
    throw new Error("Google OAuth token response must be an object.");
  }

  const accessToken = payload.access_token;
  const expiresIn = payload.expires_in;

  if (typeof accessToken !== "string" || typeof expiresIn !== "number") {
    throw new Error("Google OAuth token response is missing access token data.");
  }

  return { accessToken, expiresIn };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export type GoogleAccessToken = {
  accessToken: string;
  expiresAt: number;
};

export interface IGoogleAccessTokenProvider {
  getAccessToken(): Promise<string>;
}

import crypto from "node:crypto";

export function signJwt(
  header: Record<string, unknown>,
  payload: Record<string, unknown>,
  privateKey: string,
): string {
  const encodedHeader = base64UrlEncode(JSON.stringify(header));
  const encodedPayload = base64UrlEncode(JSON.stringify(payload));
  const signingInput = `${encodedHeader}.${encodedPayload}`;
  const signature = crypto
    .createSign("RSA-SHA256")
    .update(signingInput)
    .sign(privateKey);

  return `${signingInput}.${base64UrlEncode(signature)}`;
}

function base64UrlEncode(value: string | Buffer): string {
  return Buffer.from(value)
    .toString("base64")
    .replace(/=/g, "")
    .replace(/\+/g, "-")
    .replace(/\//g, "_");
}

